        INSERT INTO world.NpcSpeeches (NpcId, SpeechGroup, SpeechIndex, Text)
        VALUES (1, 0, 0, N'"So, I hear that you doubt my skill."'),
               (1, 0, 1, N'I don''t care about people who only believe'),
               (1, 0, 2, N'in rumors. Perhaps you should ask next time'),
               (1, 0, 3, N'and maybe you won''t get caught up in'),
               (1, 0, 4, N'such devious webs of lies.'),
               (1, 1, 0, N'Many people think we smithies are only in it'),
               (1, 1, 1, N'for the money. That''s not true I tell you!'),
               (1, 1, 2, N'"If I were looking for an easy handout, I"'),
               (1, 1, 3, N'wouldn''t have followed my father''s footsteps.'),
               (1, 2, 0, N'Excuse me... have we met before?'),
               (1, 2, 1, N'"You remind me of someone I met a long, long"'),
               (1, 2, 2, N'"time ago. Ha! Maybe in a previous life, eh?"'),
               (1, 2, 3, N'Is that so farfetched to believe?'),
               (1, 3, 0, N'Being a blacksmith is not that simple.'),
               (1, 3, 1, N'I don''t wildly smash fiery rods with a hammer.'),
               (1, 3, 2, N'"You see, a REAL weapon is crafted only by the"'),
               (1, 3, 3, N'most skilled and the most knowledgeable'),
               (1, 3, 4, N'"of smithies, if I do say so myself."'),
               (1, 4, 0, N'"The more you reinforce a weapon, the stronger"'),
               (1, 4, 1, N'"it becomes. However, the more you reinforce a"'),
               (1, 4, 2, N'weapon the harder it is to keep it from'),
               (1, 4, 3, N'breaking in the process. The more complicated'),
               (1, 4, 4, N'"an item becomes, the trickier it is, you see?"'),
               (2, 0, 0, N'"Welcome, welcome!"'),
               (2, 0, 1, N'Let everyone see how rich and powerful you are'),
               (2, 0, 2, N'by purchasing one of Yi''s fabulous dresses!'),
               (2, 1, 0, N'People always say I remind them of someone'),
               (2, 1, 1, N'else. Do I remind YOU of someone else too?'),
               (2, 1, 2, N'Please say no... *sigh*'),
               (2, 1, 3, N'Don''t worry too much. I''m getting rather used'),
               (2, 1, 4, N'"to it. After all, it''s just an appearance.."'),
               (2, 2, 0, N'Ouch! My leg!'),
               (2, 2, 1, N'I think I''m getting too old for sales work. It'),
               (2, 2, 2, N'looks like I''ll be hiring an assistant soon.'),
               (2, 2, 3, N'Are you interested in a job?'),
               (2, 3, 0, N'I''m a business woman. I know its important to'),
               (2, 3, 1, N'communicate with customers about their needs.'),
               (2, 3, 2, N'"Do you have any needs? Desires, perhaps?"'),
               (2, 3, 3, N'"Oh, darn you!"'),
               (2, 3, 4, N'"Get your mind out of the gutter, you!"'),
               (2, 4, 0, N'People like to talk big about having authentic'),
               (2, 4, 1, N'"accessories. In fact, only a few of them have"'),
               (2, 4, 2, N'"real goods. Heh, if you are ever looking for"'),
               (2, 4, 3, N'"Pra-da and don''t want to spend a fortune, come"'),
               (2, 4, 4, N'to me. What! It''s not a ''counterfeit'' Geesh!'),
               (3, 0, 0, N'"Hmm... Drink up. Drink, drink! What? How can"'),
               (3, 0, 1, N'you cure patients that way? Not to worry! I''ve'),
               (3, 0, 2, N'been doing this since before you were born!'),
               (3, 0, 3, N'I have saved countless lives! Of course I may'),
               (3, 0, 4, N'have killed a few as well. But who''s counting?'),
               (3, 2, 0, N'My medicated wine will warm you right up! One'),
               (3, 2, 1, N'cup lasts for an hour! Two cups four hours!'),
               (3, 2, 2, N'"Three cups, six hours! How much do you want?"'),
               (3, 2, 3, N'"You don''t believe me? Here, have a sample!"'),
               (3, 2, 4, N'Are you afraid of becoming ill? Trust me...'),
               (3, 3, 0, N'I''m the best Pharmacist around!'),
               (3, 3, 1, N'Don''t be so harsh to an old man... I know'),
               (3, 3, 2, N'a lot has changed now... maybe I''m not in my'),
               (3, 3, 3, N'prime anymore... back in the old days I could'),
               (3, 3, 4, N'save the dying. My skills have gone with time.'),
               (3, 4, 0, N'You wouldn''t happen to have some wine?'),
               (3, 4, 1, N'I need wine... wine...'),
               (3, 4, 2, N'*twitch*'),
               (4, 0, 0, N'I can''t take you beyond Five Fingers Mountain.'),
               (4, 0, 1, N'Too many spooks for the horses!'),
               (4, 0, 2, N'"At the slightest noise, they''ll drop ya"'),
               (4, 0, 3, N'and turn tail back to their keeper.'),
               (4, 0, 4, N'I''m so sorry!'),
               (4, 1, 0, N'There''s too many problems recently.'),
               (4, 1, 1, N'I think it''s because of Saigo Temple.'),
               (4, 1, 2, N'Rumor has it that an old dragon is buried'),
               (4, 1, 3, N'beneath the town. That¡¯s how to keep everyone'),
               (4, 1, 4, N'"from fighting. Well, that''s just what I heard."'),
               (4, 2, 0, N'"I''m too old; past my prime. Now, I''m retired."'),
               (4, 2, 1, N'I can still relate to the younger boys though.'),
               (4, 2, 2, N'"I may be old, but the wild still calls to me!"'),
               (4, 2, 3, N'~LING... LING... LIIIIIINGGGG...!~'),
               (4, 2, 4, N'"Oh yes, I was a young man once..."'),
               (4, 3, 0, N'Just reviewing the roster of those who come'),
               (4, 3, 1, N'"and go. Aye, today seems like a busy day."'),
               (4, 3, 2, N'I think this is the regular way of life.'),
               (4, 3, 3, N'China is so busy now!'),
               (4, 3, 4, N'I fear it''ll only get worse...'),
               (4, 4, 0, N'Eeech! Dang it! My arm!'),
               (4, 4, 1, N'Now even waving banners is difficult.'),
               (4, 4, 2, N'Gosh darn it!'),
               (4, 4, 3, N'"Oh, uh oh...! Getting dizzy now."'),
               (4, 4, 4, N'"I need to take a nap, tired, oopsie!"'),
               (5, 0, 0, N'Your sales are horrible! Horrible!'),
               (5, 0, 1, N'You come to me. I''ll run your business!'),
               (5, 0, 2, N'"Yes, give me your business! All of it!"'),
               (5, 0, 3, N'What? You need to think? Think about what?'),
               (5, 0, 4, N'"Fine! Go ahead, think about it."'),
               (5, 1, 0, N'Other agents brag!'),
               (5, 1, 1, N'I don''t brag! I''m very humble!'),
               (5, 1, 2, N'Most best humble agent in all of China!'),
               (5, 1, 3, N'Far and wide  scream my name! RANG!'),
               (5, 1, 4, N'"Trust me! Trust, yes? Now gimme Silver!"'),
               (5, 2, 0, N'People talk bad about me.'),
               (5, 2, 1, N'I don''t care for I am GOD!'),
               (5, 2, 2, N'People say I don''t give them the items.'),
               (5, 2, 3, N'"To cheat me so, no item in return!"'),
               (5, 2, 4, N'Fair yes? Very fair!'),
               (5, 3, 0, N'Manners are important for business!'),
               (5, 3, 1, N'Rule #1)?o ugly people.'),
               (5, 3, 2, N'Ugly people scare away customers!'),
               (5, 3, 3, N'"HAHA! No point, no point at all...!"'),
               (5, 4, 0, N'I see...'),
               (5, 4, 4, N'AN APPLE!'),
               (6, 0, 0, N'"I had a name, but... as time passed..."'),
               (6, 0, 1, N'it faded from my memory. So sad!'),
               (6, 1, 0, N'People say that I am homeless.'),
               (6, 1, 1, N'they also say that I''m poor...'),
               (6, 1, 2, N'I didn''t choose to be a beggar!'),
               (6, 1, 3, N'I had no choice!'),
               (6, 2, 0, N'A beggar has dignity too! These fools!'),
               (6, 2, 1, N'One man''s trash is another man''s treasure!'),
               (6, 3, 0, N'Please don''t look at me! Un.. unless you can'),
               (6, 3, 1, N'"spare some change. Can you spare a coin, Sir?"'),
               (6, 3, 2, N'"I''m no monkey, honest, but then again"'),
               (6, 3, 3, N'even a monkey needs to eat...'),
               (7, 0, 0, N'Throw away regrets about the past.'),
               (7, 0, 1, N'The past is in the past.'),
               (7, 0, 2, N'Let it go.'),
               (7, 1, 0, N'Business¡¦'),
               (7, 1, 1, N'means learning people¡¦'),
               (7, 1, 2, N'learn how to treat people is not easy.'),
               (7, 1, 3, N'don''t you think so?'),
               (7, 2, 0, N'I used to be a blacksmith.'),
               (7, 2, 1, N'I wasn''t good at making nice looking'),
               (7, 2, 2, N'swords but making it sharp and strong.'),
               (7, 2, 3, N'"But I never want to become a blacksmith again,"'),
               (7, 2, 4, N'and that''s why I''m doing this.'),
               (7, 3, 0, N'I gate when people say that'),
               (7, 3, 1, N'I look like somebody¡¦'),
               (7, 3, 2, N'me is me¡¦'),
               (7, 4, 0, N'Life has both dark and Brightside.'),
               (7, 4, 1, N'not only the darkness¡¦'),
               (7, 4, 2, N'not only the brightness¡¦'),
               (7, 4, 3, N'Business is same! When Bad days finished'),
               (7, 4, 4, N'good days always come!'),
               (8, 0, 0, N'Strong Martial Art doesn¡¯t mean everything.'),
               (8, 0, 1, N'There are so many other important things.'),
               (8, 0, 2, N'Do you think you can do anything'),
               (8, 0, 3, N'on your own? I don¡¯t think so¡¦'),
               (8, 0, 4, N'Try to make some friends!'),
               (8, 1, 0, N'"Easy comes, easy goes."'),
               (8, 1, 1, N'"Look around you,"'),
               (8, 1, 2, N'there are so many other important things.'),
               (8, 1, 3, N'Stop being selfish.'),
               (8, 2, 0, N'"People who became famous,"'),
               (8, 2, 1, N'They never stop train themselves.'),
               (8, 2, 2, N'They did not miss a strap tension ¡¦'),
               (8, 2, 3, N'Concentration makes strong power.'),
               (8, 3, 0, N'Do you think your Martial Art is Strong'),
               (8, 3, 1, N'enough to survive?'),
               (8, 3, 2, N'If there a little bit of doubt on my question'),
               (8, 3, 3, N'you should go back to your hometown.'),
