               (10, 1, 2, N'"If I were looking for an easy handout, I"'),
               (10, 1, 3, N'wouldn''t have followed my father''s footsteps.'),
               (10, 2, 0, N'Excuse me... have we met before?'),
               (10, 2, 1, N'"You remind me of someone I met a long, long"'),
               (10, 2, 2, N'"time ago. Ha! Maybe in a previous life, eh?"'),
               (10, 2, 3, N'Is that so farfetched to believe?'),
               (10, 3, 0, N'Being a blacksmith is not that simple.'),
               (10, 3, 1, N'I don''t wildly smash fiery rods with a hammer.'),
               (10, 3, 2, N'"You see, a REAL weapon is crafted only by the"'),
               (10, 3, 3, N'most skilled and the most knowledgeable'),
               (10, 3, 4, N'"of smithies, if I do say so myself."'),
               (10, 4, 0, N'"The more you reinforce a weapon, the stronger"'),
               (10, 4, 1, N'"it becomes. However, the more you reinforce a"'),
               (10, 4, 2, N'weapon the harder it is to keep it from'),
               (10, 4, 3, N'breaking in the process. The more complicated'),
               (10, 4, 4, N'"an item becomes, the trickier it is, you see?"'),
               (11, 0, 0, N'"Hmm... Drink up. Drink, drink! What? How can"'),
               (11, 0, 1, N'you cure patients that way? Not to worry! I''ve'),
               (11, 0, 2, N'been doing this since before you were born!'),
               (11, 0, 3, N'I have saved countless lives! Of course I may'),
               (11, 0, 4, N'have killed a few as well. But who''s counting?'),
               (11, 2, 0, N'My medicated wine will warm you right up! One'),
               (11, 2, 1, N'"cup lasts for an hour! Two cups, four hours!"'),
               (11, 2, 2, N'"Three cups, six hours! How much do you want?"'),
               (11, 2, 3, N'"You don''t believe me? Here, have a sample!"'),
               (11, 2, 4, N'Are you afraid of becoming ill? Trust me...'),
               (11, 3, 0, N'I''m the best Pharmacist around!'),
               (11, 3, 1, N'Don''t be so harsh to an old man... I know'),
               (11, 3, 2, N'a lot has changed now... maybe I''m not in my'),
               (11, 3, 3, N'prime anymore... back in the old days I could'),
               (11, 3, 4, N'save the dying. My skills have gone with time.'),
               (11, 4, 0, N'You wouldn''t happen to have some wine?'),
               (11, 4, 1, N'I need wine... wine...'),
               (11, 4, 2, N'*twitch*'),
               (12, 0, 0, N'"I had a name, but... as time passed..."'),
               (12, 0, 1, N'it faded from my memory. So sad!'),
               (12, 1, 0, N'People say that I am homeless.'),
               (12, 1, 1, N'They also say that I''m poor...'),
               (12, 1, 2, N'I didn''t choose to be a beggar!'),
               (12, 1, 3, N'I had no choice!'),
               (12, 2, 0, N'A beggar has dignity too! These fools!'),
               (12, 2, 1, N'One man''s trash is another man''s treasure!'),
               (12, 3, 0, N'Please don''t look at me! Un.. unless you can'),
               (12, 3, 1, N'"spare some change. Can you spare a coin, Sir?"'),
               (12, 3, 2, N'"I''m , honest, but then again"'),
               (12, 3, 3, N'even  needs to eat¡¦'),
               (12, 4, 0, N'The people who come here carry many things.'),
               (12, 4, 1, N'They gave me plenty of food.'),
               (13, 0, 0, N'The LostSoul guild supporting God of the Fist '),
               (13, 0, 1, N'to conquer the world is a true legend!'),
               (13, 0, 2, N'The LostSoul guild was strong and fearless.'),
               (13, 0, 3, N'I am not sure if any guild can top of that guild'),
               (13, 0, 4, N'in the time we live in¡¦.sigh.'),
               (13, 1, 0, N'I¡¯ve supported guilds for years.'),
               (13, 1, 1, N'I''ll help if you need to expand your ability '),
               (13, 1, 2, N'as well as the guild that you''re currently in.'),
               (13, 1, 3, N' '),
               (13, 2, 0, N'Often those Esoteric Buddha bastards invade '),
               (13, 2, 1, N'into the Fortress of Lost Soul.'),
               (13, 2, 2, N'"When that happens, we are counting on you."'),
               (13, 2, 3, N'"In return, I''ll share this treasure with you! "'),
               (13, 2, 4, N' '),
               (13, 3, 0, N'There''s no place like Fortress of Lost Souls'),
               (13, 3, 1, N'"to train. You may not sense it clearly,"'),
               (13, 3, 2, N'"but, the aura of the god of fist resides here!"'),
               (13, 4, 0, N'Fortress of Lost Souls is literally '),
               (13, 4, 1, N'a legendary fortress created by Mother Nature!'),
               (13, 4, 2, N'"With this advantage, invaders will be beat!"'),
               (14, 0, 0, N'¡¦'),
               (15, 0, 0, N'¡¦'),
               (16, 0, 0, N'¡¦'),
               (17, 0, 0, N'¡¦'),
               (18, 0, 0, N'Do you want to take Character Transfer Scroll?'),
               (19, 0, 0, N'¡¦.'),
               (20, 0, 0, N'¡¦.'),
               (21, 0, 0, N'¡¦.'),
               (22, 0, 0, N'¡¦.'),
               (23, 0, 0, N'Deal. I¡¯ll let you keep God of the Fist 5 set '),
               (23, 0, 1, N'for a while. Make sure to return it.'),
               (24, 0, 0, N'Deal. I¡¯ll let you keep God of the Fist 5 set '),
               (24, 0, 1, N'for a while. Make sure to return it.'),
               (25, 0, 0, N'Deal. I¡¯ll let you keep God of the Fist 5 set '),
               (25, 0, 1, N'for a while. Make sure to return it.'),
               (26, 0, 0, N'Deal. I¡¯ll let you keep God of the Fist 5 set '),
               (26, 0, 1, N'for a while. Make sure to return it.'),
               (51, 0, 0, N'"The era of the Old Generation is over,"'),
               (51, 0, 1, N'brilliant heroes like Shrin Kae and'),
               (51, 0, 2, N'Guardian Stah Reiki are no longer in their'),
               (51, 0, 3, N'prime. This world needs the pioneering spirit'),
               (51, 0, 4, N'of young people.'),
               (51, 1, 0, N'"Shrin Kae is a powerful warrior, but"'),
               (51, 1, 1, N'its his daughter that surprises me...'),
               (51, 1, 2, N'Maybe I should pay her a visit sometime...'),
               (51, 2, 0, N'Guardian Fohchoy?'),
               (51, 2, 1, N'"Well, it''s funny, people are sometimes far too"'),
               (51, 2, 2, N'"sure of themselves, they feel as if they are"'),
               (51, 2, 3, N'"superior, but in all actuality"'),
               (51, 2, 4, N'they are nobody.'),
               (51, 3, 0, N'"Guardian Stah Reiki has a stubborn temper,"'),
               (51, 3, 1, N'he thinks that only he can solve the'),
               (51, 3, 2, N'problems. It''s why he isn''t informed of real'),
               (51, 3, 3, N'"situations. Frankly speaking, he is just too"'),
               (51, 3, 4, N'"controlling, and this has made him weak."'),
               (51, 4, 0, N'Its time to show the others what the Nangin'),
               (51, 4, 1, N'are really about. They want an end to all the'),
               (51, 4, 2, N'"wars and suffering, then they must prove that"'),
               (51, 4, 3, N'they....'),
               (51, 4, 4, N'"Hmm, we must wait and see."'),
               (52, 0, 0, N'Ahah.'),
               (52, 0, 1, N'Ehlec Teroh is so great.'),
               (52, 0, 2, N'I never thought he could draw a Head Master'),
               (52, 0, 3, N'like me into becoming Nangin.'),
               (52, 0, 4, N'The flow of history is irreversible!'),
               (52, 1, 0, N'You can only join the Nangin after reaching'),
               (52, 1, 1, N'"Master Level, because this is a place for"'),
               (52, 1, 2, N'strong players! Don''t come here'),
               (52, 1, 3, N'if you are not strong enough. We will'),
               (52, 1, 4, N'just ignore people under Master Level.'),
               (52, 2, 0, N'"I need to drink something, huh."'),
               (52, 2, 1, N'"I seldom drink now,"'),
               (52, 2, 2, N'I will only drink when I think no one'),
               (52, 2, 3, N'will notice.'),
               (52, 3, 0, N'"The stone that give us our power,"'),
               (52, 3, 1, N'it is as equally important as your life.'),
               (52, 3, 2, N'We have to try our best to protect it in'),
               (52, 3, 3, N'"every battle, and we will have to"'),
               (52, 3, 4, N'try our best to destroy other Faction''s stone.'),
               (52, 4, 0, N'Ehlec Teroh is a noble leader. Look how he'),
               (52, 4, 1, N'attracts the Martial Masters of the three'),
               (52, 4, 2, N'"Factions, and keeps us free from internal"'),
               (52, 4, 3, N'"strife. As a comparison, leaders of the three"'),
               (52, 4, 4, N'Factions should take a look at themselves.'),
               (53, 0, 0, N'"Ehlec Teroh has a magnetic personality,"'),
               (53, 0, 1, N'"I wouldn''t be who I am without him,"'),
               (53, 0, 2, N'not to mention these people and the Nangin!'),
               (53, 0, 3, N'I know a lot about the Noble Dragon''s'),
               (53, 0, 4, N'"Martial Arts, even though I didn''t train long."'),
               (54, 0, 0, N'The three major Factions always provoked us'),
               (54, 0, 1, N'due to our powerful strength. If it wasn''t for'),
               (54, 0, 2, N'"the help of Ehlec Teroh we would have. Well,"'),
               (54, 0, 3, N'"he reformed the Nangin, and he appointed me"'),
               (54, 0, 4, N'to be the first to follow in his footsteps!'),
               (55, 0, 0, N'But we were also pushed by the three major'),
               (55, 0, 1, N'Factions. So when Ehlec Teroh proposed to'),
               (55, 0, 2, N'"accept us, we agreed immediately."'),
               (55, 0, 3, N'"After all, the three major Factions were our"'),
               (55, 0, 4, N'biggest enemy!'),
               (56, 0, 0, N'"I belong to the Xaotei Family, we''re the best"'),
               (56, 0, 1, N'"blacksmiths. No boasting, but no one in"'),
               (56, 0, 2, N'this world can match our forging skills.'),
               (56, 0, 3, N'"Those blacksmiths in the three Factions, they"'),
               (56, 0, 4, N'are just our distant relatives'' apprentices.'),
               (56, 1, 1, N'I used to have faith in religion;'),
               (56, 1, 2, N'"however, the blacksmith''s job"'),
               (56, 1, 3, N'fits me physically.'),
               (56, 1, 4, N'"So, I changed to do this job"'),
               (56, 2, 0, N'with no regret'),
               (56, 2, 1, N'"I forged Encharo knife, the disappeared guardian"'),
               (56, 2, 2, N'once'),
               (56, 2, 3, N'Don''t you think it''s gonna last long?'),
               (56, 2, 4, N'Relationship is stange'),
               (56, 3, 1, N'You think I can bend a cast iron with my hand?'),
               (56, 3, 2, N'Ha ha. I don''t have '),
               (56, 3, 3, N'such power'),
               (56, 4, 1, N'I heard that our  friend from Skyfall party'),
               (56, 4, 2, N'is really good at work'),
               (56, 4, 3, N'That''s incredible.'),
               (57, 0, 0, N'"Aha, you need anything?"'),
               (57, 0, 1, N'"Why don''t you take a look first, there maybe"'),
               (57, 0, 2, N'something you can use.'),
               (57, 1, 1, N'Most merchants from the Cloud Power party'),
               (57, 1, 2, N'don''t really like the blacksmith'),
               (57, 1, 3, N'So do I'),
               (57, 1, 4, N'because it has an unfair monopoly system'),
               (57, 2, 1, N'Where did it happen? Where on earth do you think'),
               (57, 2, 2, N'Ha ha. You can guess.'),
               (57, 3, 1, N'"Um, The cloth I''m wearing now?"'),
               (57, 3, 2, N'Doesn''t it beautiful? I did it myself.'),
               (57, 4, 1, N'It''s so lucky that '),
               (57, 4, 2, N'the Cloud power refuses the blacksmith'),
               (57, 4, 3, N'or else the Wulin will be boring'),
               (57, 4, 4, N'and evil'),
               (58, 0, 0, N'"Many doctors in this world lack ethics,"'),
               (58, 0, 1, N'they only care about making money...'),
               (58, 0, 2, N'"I''m really sick of those so called doctors,"'),
               (58, 0, 3, N'"very sick, such a disgrace of a doctor''s soul!"'),
               (58, 1, 1, N'Finish your sentence'),
               (58, 1, 2, N'do not mumble'),
               (58, 2, 1, N'The guadian Encharo saved my life for many times'),
               (58, 2, 2, N'That''s why I can still work'),
               (58, 2, 3, N'nowadays'),
               (58, 2, 4, N'"Being a doctor at this age is annoying, yet"'),
               (58, 3, 0, N'I gain a fortune so it can''t help '),
               (58, 3, 1, N'Money is God'),
               (58, 3, 2, N'isn''t it?'),
               (58, 4, 1, N'Zzzzz'),
               (59, 0, 0, N'Where do you want to go?'),
               (59, 0, 1, N'"Just tell me your destination, and I will"'),
               (59, 0, 2, N'send you there immediately.'),
               (59, 0, 3, N'You will be experiencing the fastest travel'),
               (59, 0, 4, N'"in your life, so hang on!"'),
               (59, 1, 1, N'The Lunar Master'),
               (59, 1, 2, N'is the greatest'),
               (59, 1, 3, N'"If we don''t have him, life will be more terrible"'),
               (59, 1, 4, N'than having the Moon Shadow swordmen.'),
               (59, 2, 1, N'Is this your first time seeing a silver fox?'),
               (59, 2, 2, N'The silver fox is innocent and loyal.'),
               (59, 2, 3, N'Its loyalty is greater than human beings'''),
               (59, 2, 4, N'"Being a doctor at this age is annoying, somehow"'),
               (59, 3, 1, N'The say the horse is fast'),
               (59, 3, 2, N'but for me '),
               (59, 3, 3, N'the silver fox is much faster'),
               (59, 4, 1, N'The conflict between the Moon Shadow swordmen'),
               (59, 4, 2, N'needs to be compromised as soon as possible'),
               (59, 4, 3, N'That''s very sad.'),
               (60, 0, 0, N'......'),
               (60, 0, 1, N'"Leave me alone, or you will have to accept the"'),
               (60, 0, 2, N'consequences!'),
               (60, 1, 1, N'The Grand Master is amazing.'),
               (60, 1, 2, N'He can gather '),
               (60, 1, 3, N'and unite people'),
               (60, 1, 4, N'which normall people cannot acheive'),
               (60, 2, 1, N'Most people rarely accept'),
               (60, 2, 2, N'difference'),
               (60, 2, 3, N'But we need to respect the difference'),
               (60, 2, 4, N'as we''re all different'),
               (60, 3, 0, N'in oder to live peacefully'),
               (60, 3, 1, N'You have to pay respect to superiors'),
               (60, 3, 2, N'and inferiors'),
               (60, 3, 3, N'It''s a shame that people these days '),
               (60, 3, 4, N'do not pay enough respect to the inferiors'),
               (60, 4, 1, N'you mean the white tiger skin?'),
               (60, 4, 2, N'It''s a  gift fromthe Moon Shadow swordmen'),
               (60, 4, 3, N'"His master, Lunar Master, give it to me"'),
               (60, 4, 4, N'which becomes my favorite.'),
               (61, 0, 0, N'I''m also in this agent business to...to...to..'),
               (61, 0, 1, N'make money! No one gates money right?'),
               (61, 0, 2, N'Of...of course I will do it.'),
               (61, 0, 3, N'Key! Is there any thing you want me to sell?'),
               (61, 1, 1, N'You can try!'),
               (61, 1, 2, N'"Even though it''s deceptive, you earn money."'),
               (61, 2, 1, N'"At first , it was with the blacksmith"'),
               (61, 2, 2, N'but women always look down on this kind of stuff'),
               (61, 2, 3, N'but time changes.'),
               (61, 2, 4, N'Do not disregard this old lady'),
               (61, 3, 0, N'"I am a great seller, aren''t I?"'),
               (61, 3, 1, N'What? old-fashioned cloth?'),
               (61, 3, 2, N'What''s wrong with you people?'),
               (61, 3, 3, N'How do you measure old-fashioned style?'),
               (61, 3, 4, N'Huh? Explain!'),
               (61, 4, 1, N'She has a sharp tongue as her best armor'),
               (61, 4, 2, N'Don''t you feel it?'),
               (61, 4, 3, N'There is no shortcut in this business'),
               (61, 4, 4, N'I am just only a demon'),
               (62, 0, 0, N'"Aha, can I help you with something?"'),
               (62, 0, 1, N'"Only you can imagine, there is nothing that we"'),
               (62, 0, 2, N'"don''t sell. I have the highest quality goods,"'),
               (62, 0, 3, N'better than the goods in the other'),
               (62, 0, 4, N'three Factions! Wanna take a look?'),
               (62, 1, 1, N'I''ve been tired lately'),
               (62, 1, 2, N'"The better the business is, the more tired I am"'),
               (62, 1, 3, N'That''s unavoidable'),
               (62, 2, 1, N'ZhuHuang is better than I thought'),
               (62, 2, 2, N'Each sanctuary '),
               (62, 2, 3, N'has its own strange rules'),
               (62, 2, 4, N'like a barrier'),
               (62, 3, 0, N'You can find freedom here'),
               (62, 3, 1, N'Married'),
               (62, 3, 2, N'with 5 kids'),
               (62, 3, 3, N'Ha ha ha hah. Interested?'),
               (62, 4, 1, N'Do not overthink when you look for it'),
               (62, 4, 2, N'Just shout out'),
               (62, 4, 3, N'How different one''s life is?'),
               (62, 4, 4, N'You only live once. All the same.'),
               (63, 0, 0, N'Life is all about gambling!'),
               (63, 0, 1, N'"Aha, it applies to buying, fighting and"'),
               (63, 0, 2, N'marriage! Only won by people who made'),
               (63, 0, 3, N'the right bet! Wanna play with me?'),
               (63, 1, 1, N'Do not think about the cost when you bet'),
               (63, 1, 2, N'ever'),
               (63, 1, 3, N'You think that you spend money'),
               (63, 1, 4, N'as equal as the cost'),
               (63, 2, 1, N'You keep saying about the cost'),
               (63, 2, 2, N'I never seen anyone who keeps complane about it'),
               (63, 2, 3, N'successful'),
               (64, 0, 0, N'Mercy me! I''m just a beggar!'),
               (64, 0, 1, N'Really!!!! I''m not lying!'),
               (64, 0, 2, N'"Just a little help, I have a family to feed!"'),
               (64, 1, 1, N'I will be thankful '),
               (64, 1, 2, N'if you give me some money'),
               (65, 0, 0, N'It feels good to serve other people.'),
               (65, 0, 1, N'"At least you don''t have to worry about food,"'),
               (65, 0, 2, N'and you have the excess money to support'),
               (65, 0, 3, N'your family.'),
               (65, 0, 4, N'"Not bad, hehe!"'),
               (65, 1, 1, N'Work hard for the Grand Master'),
               (65, 1, 2, N'who hands you freedom!'),
               (66, 0, 0, N'Ehlec Teroh has an unbelievably charming'),
               (66, 0, 1, N'"personality, and for that reason"'),
               (66, 0, 2, N'we are willing to serve him as Guards.'),
               (66, 0, 3, N'"Well, hope he can fulfill his promise"'),
               (66, 0, 4, N'to China.'),
               (66, 1, 1, N'"To leave the Skyfall party,"'),
               (66, 1, 2, N'you need strong soul'),
               (66, 1, 3, N'I''m alive today ');

        INSERT INTO world.NpcSpeeches (NpcId, SpeechGroup, SpeechIndex, Text)
        VALUES (66, 1, 4, N'because I can overcome those pains'),
               (67, 0, 0, N'......'),
               (67, 0, 1, N'What you looking at?'),
               (67, 0, 2, N'Have you even seen a Martial Master?'),
               (67, 0, 3, N'"Get lost, kid!"'),
               (68, 0, 0, N'......'),
               (68, 0, 1, N'"The Chief says that, as of gate, things"'),
               (68, 0, 2, N'have been chaotic. We better not let'),
               (68, 0, 3, N'anyone that looks suspicious in.'),
               (68, 0, 4, N'"Uh, you look suspicious."'),
               (68, 1, 0, N'Let''s have a talk...'),
               (69, 0, 0, N'Tell me if you need anything.'),
               (69, 0, 1, N'Nothing?'),
               (69, 0, 2, N'"So, what you doing here if you need nothing?"'),
               (69, 0, 3, N'The Martial Soul is so easily mocked!'),
               (70, 0, 0, N'It feels good to serve other people.'),
               (70, 0, 1, N'"At least you don''t have to worry about food,"'),
               (70, 0, 2, N'and you have the  to support'),
               (70, 0, 3, N'your family.'),
               (70, 0, 4, N'"Not bad, hehe!"'),
               (101, 0, 0, N'"I have only one wish, really. And that wish"'),
               (101, 0, 1, N'is to see the three Factions united.'),
               (101, 0, 2, N'I believe that under the rule of the Imperial'),
               (101, 0, 3, N'"Noble Dragon, China can become the most"'),
               (101, 0, 4, N'powerful nation in the world!'),
               (101, 1, 0, N'"You are going to attend to the wedding, yes?"'),
               (101, 1, 1, N'"The marriage of my daughter Mau Li, of course!"'),
               (101, 1, 2, N'The whole empire is invited to this event!'),
               (101, 1, 3, N'"I dare not say its mandatory, but escorts will"'),
               (101, 1, 4, N'make sure all dwellings are empty at the time.'),
               (101, 2, 0, N'Ehlec Teroh... Ehlec Teroh...'),
               (101, 2, 1, N'What a coveted name.'),
               (101, 3, 0, N'The Grand Tiger Guardian is a powerful adversary'),
               (101, 3, 1, N'Unfortunately he suffers from a large ego.'),
               (101, 3, 2, N'"It not always a bad thing, but can lead one to"'),
               (101, 3, 3, N'under-estimate their foes. This is rather good'),
               (101, 3, 4, N'for the Noble Dragon though...'),
               (101, 4, 0, N'Master Yang was a dear friend of mine.'),
               (101, 4, 1, N'A true leader. But alas he is no longer'),
               (101, 4, 2, N'with us. Such a shame. That man was the very'),
               (101, 4, 3, N'essence of greatness!'),
               (102, 0, 0, N'There is no such thing as total absolute.'),
               (102, 0, 1, N'Good and evil... who''s to say?'),
               (102, 0, 2, N'"Once you understand this, good can be evil"'),
               (102, 0, 3, N'and evil also can be good.'),
               (102, 0, 4, N'*Hic* Maybe too much wine?'),
               (102, 1, 0, N'My hair loss is getting serious these days!'),
               (102, 1, 1, N'I am told beautiful people like me become'),
               (102, 1, 2, N'ravaged by time in their Golden Years.'),
               (102, 1, 3, N'Ugh!'),
               (102, 2, 0, N'"Key you... remember, always bring me wine!"'),
               (102, 2, 1, N'"If you do, I can get you a word with Shrin Kae"'),
               (102, 2, 2, N'"*hic*... Haha, don''t forget!"'),
               (102, 3, 0, N'I''m not drunk yet! Haha!'),
               (102, 4, 0, N'"Shhh, I may be an Elder, but I''m also a secret"'),
               (102, 4, 1, N'Taoist Master! Foosha! *hic*'),
               (103, 0, 0, N'Guardian Long has fine swordsmanship.'),
               (103, 0, 1, N'I can sense his loyalty to our Guardian.'),
               (103, 0, 2, N'"With those perfect moves, his Sword Skill"'),
               (103, 0, 3, N'is definitely better than the Guardian''s.'),
               (103, 1, 0, N'Mau Li...'),
               (103, 1, 1, N'Do you think she''ll be alright?'),
               (103, 1, 2, N'"Huh? Oh, I''m sorry, I was just thinking"'),
               (103, 1, 3, N'"about her. So, where were we again?"'),
               (103, 2, 0, N'Our Guardian is an outstanding person.'),
               (103, 2, 1, N'He is also my Master. I have a lot of respect'),
               (103, 2, 2, N'for him. He''s quite a scholar once you get to'),
               (103, 2, 3, N'know him a bit.'),
               (103, 3, 0, N'I train everyday to be the best.'),
               (103, 3, 1, N'A Chinese secret -'),
               (103, 3, 2, N'Practice makes perfect!'),
               (103, 4, 0, N'"Train with me, and you can"'),
               (103, 4, 1, N'become a champion!'),
               (104, 0, 0, N'Hello! You''re a strong looking individual!'),
