               (204, 4, 1, N'She''s an amazing warrior.'),
               (204, 4, 2, N'"It''s a shame she trusted Quon, but that"'),
               (204, 4, 3, N'was his undoing. Its best we don''t mention it'),
               (204, 4, 4, N'to her...'),
               (205, 0, 0, N'"After the former Guardian passed away, I"'),
               (205, 0, 1, N'assigned Vice Lord until a proper official was'),
               (205, 0, 2, N'"appointed. Accepting my duty, I left my family"'),
               (205, 0, 3, N'"and home. But when I arrived, they had no more"'),
               (205, 0, 4, N'use for me. Guardian Fohchoy was chosen.'),
               (205, 1, 0, N'Mandolins are able to manipulate sound waves'),
               (205, 1, 1, N'to placed attack! Its quite'),
               (205, 1, 2, N'an ingenious idea if you think about it!'),
               (205, 1, 3, N'Never underestimate the ingenuity of'),
               (205, 1, 4, N'the Royal Serpent I always say!'),
               (205, 2, 0, N'"Here in the Royal Serpent, snowflakes"'),
               (205, 2, 1, N'dance in the sky all year long. Its so'),
               (205, 2, 2, N'beautiful. I feel like watching snowflakes'),
               (205, 2, 3, N'with my father.'),
               (205, 3, 0, N'"Whenever I think of my father, I can''t help"'),
               (205, 3, 1, N'but to feel sad. I miss seeing my old friends'),
               (205, 3, 2, N'too but there is nothing we can do.'),
               (205, 4, 0, N'The Royal Serpent are really wonderful.'),
               (205, 4, 1, N'"Now that MauLi has joined us,"'),
               (205, 4, 2, N'our training has been really intense!'),
               (205, 4, 3, N'She is very skilled in the Arts of the Dragon.'),
               (205, 4, 4, N'Its good to have this upper hand in battle.'),
               (206, 0, 0, N'My hammer does not work with wine!'),
               (206, 0, 1, N'The blasted thing keeps landing on my hand!'),
               (206, 0, 2, N'It would seem that I may have to give up'),
               (206, 0, 3, N'drinking? Such an unbearable thought!'),
               (206, 1, 0, N'Oh the weather outside is frightful?'),
               (206, 1, 1, N'Yet alas its so delightful?'),
               (206, 1, 2, N'Yadda yadda something snow?'),
               (206, 1, 3, N'"Let it snow, let it snow, let it snow!"'),
               (206, 2, 0, N'What mortal man isn''t interested in money?'),
               (206, 2, 1, N'"Hah, you can be sure I am. You can''t live"'),
               (206, 2, 2, N'"without it. You need to pay for food, housing,"'),
               (206, 2, 3, N'and equipment.'),
               (206, 3, 0, N'Have you tried your hand at smiting? Here!'),
               (206, 3, 1, N'"Hmm? Although the workmanship isn''t beautiful,"'),
               (206, 3, 2, N'I can''t find fault with the piece. I''m'),
               (206, 3, 3, N'unable to keep from sighing each time'),
               (206, 3, 4, N'I see it.'),
               (207, 0, 0, N'STOP IT!'),
               (207, 0, 1, N'STOP! YOU''RE STILL DOING IT!'),
               (207, 0, 2, N'DON''T LOOK AT ME! I''M UGLY!'),
               (207, 0, 3, N'UGLY! JUST LOOK AT THESE RAGS!'),
               (207, 1, 0, N'Did Blacksmith Kew ask you do to something'),
               (207, 1, 1, N'for him? Nasty! I would never be caught dead'),
               (207, 1, 2, N'people like me will not touch those rocks...'),
               (207, 1, 3, N'I really don''t want to touch those things any'),
               (207, 1, 4, N'more.'),
               (207, 2, 0, N'"In fact, these clothes don''t keep me warm,"'),
               (207, 2, 1, N'I''m dressing like this for the business.'),
               (207, 2, 2, N'Men always say they feel warm when they see');

        INSERT INTO world.NpcSpeeches (NpcId, SpeechGroup, SpeechIndex, Text)
        VALUES (207, 2, 3, N'me... I just refuse to answer.'),
               (207, 3, 0, N'Did Neima make it into the Messengers?'),
               (207, 3, 1, N'"Uh, I don''t know how he got it."'),
               (207, 3, 2, N'"Forget about it, talking behind someone''s"'),
               (207, 3, 3, N'back is not good.'),
               (207, 4, 0, N'"Guild Director Koh is quite interesting,"'),
               (207, 4, 1, N'but he has a big mouth. Did you know the'),
               (207, 4, 2, N'items that he kept were never lost? Now that'),
               (207, 4, 3, N'surprised me.'),
               (208, 0, 0, N'Those Snowy Northern Mountains just don''t'),
               (208, 0, 1, N'stop snowing....'),
               (208, 0, 2, N'I can''t even gather the herbs I need.'),
               (208, 0, 3, N'"Oh my, what about those patients...?"'),
               (208, 0, 4, N'There just isn''t enough medicine.'),
               (208, 1, 0, N'"I don''t know who stole them, but"'),
               (208, 1, 1, N'my herb count has fallen short today.'),
               (208, 1, 2, N'"If I find out who has taken them,"'),
               (208, 1, 3, N'I will teach him a lesson!'),
               (208, 2, 0, N'"Hm, the accident that happened to Elder Deison"'),
               (208, 2, 1, N'and Lord Zhou a few days ago was a huge'),
               (208, 2, 2, N'surprise. How could they be caught off their'),
               (208, 2, 3, N'guard so easily when both of them have such'),
               (208, 2, 4, N'powerful Martial Arts?'),
               (208, 3, 0, N'"In this world, you can''t always rely on luck."'),
               (208, 3, 1, N'"Luck is important mind you, but you need"'),
               (208, 3, 2, N'to have strength to back it up. What if you'),
               (208, 3, 3, N'"have no luck and just strength? Well, you''d"'),
               (208, 3, 4, N'still be vulnerable to opponents'' attacks.'),
               (208, 4, 0, N'Raa!'),
               (208, 4, 1, N'Raa!'),
               (208, 4, 2, N'Raa!'),
               (208, 4, 3, N'"Boom,"'),
               (208, 4, 4, N'Dee-ay!'),
               (209, 0, 0, N'I heard that gate Master Tai is always talking'),
               (209, 0, 1, N'behind my back. Oh....that old fellow.'),
               (209, 0, 2, N'I don''t remember ever offending him.'),
               (209, 0, 3, N'"Well, he better not try to ruin my business!"'),
               (209, 1, 0, N'Telekinesis is a very exact science! Once'),
               (209, 1, 1, N'"mastered, it changes your entire perspective."'),
               (209, 1, 2, N'"Oh yes, it''s really wonderful!"'),
               (209, 2, 0, N'"People wish to know how my telekinesis works,"'),
               (209, 2, 1, N'but it simply is not something that can be'),
               (209, 2, 2, N'taught. When you can bend the world with your'),
               (209, 2, 3, N'"mind, you may begin to understand."'),
               (209, 3, 0, N'"A few days ago, gate Master Tai was"'),
               (209, 3, 1, N'saying some nasty things behind my back.'),
               (209, 3, 2, N'That jerk just wont go away!'),
               (209, 3, 3, N'"Oh, we have all kinds of people in the"'),
               (209, 3, 4, N'Royal Serpent.'),
               (210, 0, 0, N'May I help you..?'),
               (210, 0, 1, N'Don''t you want to know something from me just'),
               (210, 0, 2, N'"like all the others? Ah, but heaven''s secrets"'),
               (210, 0, 3, N'can''t be divulged.'),
               (210, 1, 0, N'"Haha, look at me,"'),
               (210, 1, 1, N'what do you think? Am I handsome?'),
               (210, 1, 2, N'"Well, I think for an old man like me to look"'),
               (210, 1, 3, N'this young is really amazing. Hahahahah!!!'),
               (210, 2, 0, N'"This must be some kind of charm. Oh, was"'),
               (210, 2, 1, N'someone talking behind my back?'),
               (210, 2, 2, N'They must be jealous. Young people'),
               (210, 2, 3, N'these days!'),
               (210, 3, 0, N'"Well, it''s such a great thing to help people"'),
               (210, 3, 1, N'set up their Factions. If a young lady'),
               (210, 3, 2, N'"kisses me, I will gladly help set up a Faction"'),
               (210, 3, 3, N'for her. What do you think?'),
               (210, 3, 4, N'Not bad right? Haha.'),
               (210, 4, 0, N'"The former Lord was a handsome guy,"'),
               (210, 4, 1, N'"and well... Guardian Fohchoy isn''t bad either,"'),
               (210, 4, 2, N'but they are all no match for me! Haha!'),
               (211, 0, 0, N'"Do you want to do some business? Oh,"'),
               (211, 0, 1, N'you wanna learn how to do business?'),
               (211, 0, 2, N'"Well, you will need a lot money and wisdom!"'),
               (211, 0, 3, N'And you will need to know how to read'),
               (211, 0, 4, N'"people... Key, don''t leave!!"'),
               (211, 1, 0, N'I got these spectacles from the remote west.'),
               (211, 1, 1, N'"These are magical objects, for they will help"'),
               (211, 1, 2, N'those with bad eyesight. Don''t you think'),
               (211, 1, 3, N'that it''s strange? If worn by people with good'),
               (211, 1, 4, N'"eyesight, their eyesight may become worse..."'),
               (211, 2, 0, N'"You can sell items here, I will sell them"'),
               (211, 2, 1, N'for you at a good price. It isn''t selling?'),
               (211, 2, 2, N'"You can leave it with me, it may sell"'),
               (211, 2, 3, N'eventually.'),
               (211, 3, 0, N'I heard that there is a famous medicine'),
               (211, 3, 1, N'that will heal wounds quickly. People'),
               (211, 3, 2, N'call it Cure All Medicine. I myself'),
               (211, 3, 3, N'"have never tried it, but I want to see"'),
               (211, 3, 4, N'how it works. I don''t think it''s poison.'),
               (211, 4, 0, N'Agents need to have good manners. As a'),
               (211, 4, 1, N'"businessman, you know its important to"'),
               (211, 4, 2, N'communicate with people. You should'),
               (211, 4, 3, N'"never deceive your self or others, right?"'),
               (212, 0, 0, N'"Well, won''t you come in?"'),
               (212, 0, 1, N'"It''s cheap but good, and your satisFaction"'),
               (212, 0, 2, N'is guaranteed! How is it? Want to buy it?'),
               (212, 0, 3, N'"Well, how about this, you examine it first!"'),
               (212, 1, 0, N'What do you think? My clothes are really'),
               (212, 1, 1, N'"beautiful, right? It totally highlights"'),
               (212, 1, 2, N'"my body''s curves!! Haha, of course I"'),
               (212, 1, 3, N'wear them so I can make a bit more money.'),
               (212, 2, 0, N'My grandpa says that I loved fans'),
               (212, 2, 1, N'"when I was a kid. Oh yes, I still love"'),
               (212, 2, 2, N'"them! Haha, that''s why I''m holding a"'),
               (212, 2, 3, N'fan right now.'),
               (212, 3, 0, N'"I can''t put down this bundle, because"'),
               (212, 3, 1, N'there are a lot valuable items inside of it.'),
               (212, 3, 2, N'I would become a beggar if I lost it.'),
               (212, 3, 3, N'"So I just carry it, oh, but it''s so heavy!"'),
               (212, 4, 0, N'Guild Director Koh is quite interesting.'),
               (212, 4, 1, N'"He doesn''t look good, but he always tries to"'),
               (212, 4, 2, N'convince people he is a handsome guy.'),
               (212, 4, 3, N'"Haha, he even tried to compare with me!"'),
               (212, 4, 4, N'"Silly old fellow, haha!!"'),
               (213, 0, 0, N'"I lost everything from gambling, but"'),
               (213, 0, 1, N'in the end I learned how to gamble.'),
               (213, 0, 2, N'"Anyway, it''s an old story..."'),
               (213, 0, 3, N'"Come on, lets have some fun!"'),
               (213, 1, 0, N'Gambling is a way of life. Casinos'),
               (213, 1, 1, N'are the epitome of China.'),
               (213, 1, 2, N'"No matter how good you are in combat,"'),
               (213, 1, 3, N'"here, you are just a man on the street."'),
               (213, 1, 4, N'Only money speaks in here.'),
               (213, 2, 0, N'"If you like to gamble, that is just the"'),
               (213, 2, 1, N'primary stage of gambling. Real'),
               (213, 2, 2, N'"gambling is never that simple, you"'),
               (213, 2, 3, N'need to develop a great technique.'),
               (213, 3, 0, N'Vital Gambling is something really exciting.'),
               (213, 3, 1, N'Winning or losing will happen in a flash.'),
               (213, 3, 2, N'"In other words, the outcome is clear,"'),
               (213, 3, 3, N'that''s the beauty of the gamble.'),
               (213, 3, 4, N'Gambling is terrific! Hahaha!'),
               (213, 4, 0, N'The world of gambling is wonderful!'),
               (213, 4, 1, N'"It holds all the emotions of life,"'),
               (213, 4, 2, N'and exposes them in an instant.'),
               (213, 4, 3, N'It¡¯s a game for only the very brave.'),
               (213, 4, 4, N'Want to bet something big?'),
               (214, 0, 0, N'Mmm. This wine smells good. This'),
               (214, 0, 1, N'old man is such a glutton. I just can¡¯t'),
               (214, 0, 2, N'help it... Huh.. all right. We must enjoy'),
               (214, 0, 3, N'"wine and song while we can, life is short!"'),
               (214, 1, 0, N'"Men are creatures with great perseverance,"'),
               (214, 1, 1, N'there is no way to change that.'),
               (214, 1, 2, N'How can you call yourself a man without it?'),
               (214, 1, 3, N'I am constantly pursuing human nature and'),
               (214, 1, 4, N'that¡¯s why I became what I am today.'),
               (214, 2, 0, N'When are you going to throw away that bundle'),
               (214, 2, 1, N'on your back? Are you preparing that'),
               (214, 2, 2, N'for begging? Aha! Nothing wrong'),
               (214, 2, 3, N'with being a beggar.'),
               (214, 3, 0, N'Everyday I drink a little. That is the'),
               (214, 3, 1, N'"only thing I am keen on. Eh, that''s"'),
               (214, 3, 2, N'"life. Come on, just relax a bit. Life is"'),
               (214, 3, 3, N'too hard.'),
               (215, 0, 0, N'Argh! How come I don¡¯t feel cold?'),
               (215, 0, 1, N'How can I call myself a Guard of Ling Chi'),
               (215, 0, 2, N'Fortress if I can¡¯t stand such cold weather?'),
               (215, 0, 3, N'Get out of my way. I''m on duty.'),
               (215, 1, 1, N'I¡¯m not sleeping!'),
               (215, 2, 0, N'Hello?'),
               (215, 3, 0, N'Guards are the symbol of bravery and courage.'),
               (215, 3, 1, N'"It would be wise to mind yourself, and"'),
               (215, 3, 2, N'not mess with us!'),
               (215, 4, 0, N'!!!!!'),
               (215, 4, 1, N'You scared me!'),
               (216, 0, 0, N'There is a forbidden area to the Northern'),
               (216, 0, 1, N'Mountains. It lies behind Impetrate Valley of'),
               (216, 0, 2, N'Shaoyuan Mountain. People say that'),
               (216, 0, 3, N'there is an immortal there who can control'),
               (216, 0, 4, N'the cold wind. Do you think it''s true?'),
               (216, 1, 0, N'I¡¯m not like the other Guards.'),
               (216, 1, 1, N'"I¡¯m much Flutter, don''t you think?"'),
               (216, 1, 2, N'"Well, you''re a nice person."'),
               (216, 1, 3, N'"I admire that about you. In fact, you''re"'),
               (216, 1, 4, N'just my type!'),
               (216, 2, 0, N'Please inform me if you wish to enlist into'),
               (216, 2, 1, N'"the Royal Army. If you don''t, no one will"'),
               (216, 2, 2, N'morn your death if you are a casualty of'),
               (216, 2, 3, N'war?'),
               (216, 3, 0, N'Ikusa Mountain is a well known landmark.'),
               (216, 3, 1, N'"A few years back, only Adepts could survive."'),
               (216, 3, 2, N'"Now, everyone and their grandmother waltz"'),
               (216, 3, 3, N'right in like they own the place!'),
               (216, 4, 0, N'"Oh, I feel sleepy..."'),
               (216, 4, 1, N'I can''t keep my eyes open.'),
               (216, 4, 2, N'I¡¯m exhausted after my double shift?'),
               (217, 0, 0, N'When your strength reaches its full potential'),
               (217, 0, 1, N'you can forget about strategy.'),
               (217, 0, 2, N'"Until then, you better use your brains."'),
               (217, 0, 3, N'This mentality can make or break your'),
               (217, 0, 4, N'survival. Hahah.'),
               (217, 1, 0, N'Oh how I knew Miko''s telekinesis technique!'),
               (217, 1, 1, N'My Commanding Officer would never'),
               (217, 1, 2, N'"allow it though. As per my duty, I would"'),
               (217, 1, 3, N'need to. Its such a disappointment.'),
               (217, 2, 0, N'"At the slightest doubt of your manage,"'),
               (217, 2, 1, N'seek me out immediately!'),
               (217, 2, 3, N'That''s an order!'),
               (217, 3, 0, N'People say you look like an Guard? Well...'),
               (217, 3, 1, N'Why don¡¯t you just write yourself a nametag'),
               (217, 3, 2, N'"saying, ""Hello! I''m Guard Captain Nobody!"""'),
               (217, 3, 3, N'Hahah!'),
               (217, 4, 0, N'Guards go through rigorous training! Not'),
               (217, 4, 1, N'everyone has the chance to wave the Royal'),
               (217, 4, 2, N'"flag, so don''t play with it or you will get"'),
               (217, 4, 3, N'into trouble!'),
               (218, 0, 0, N'The other Factions are really bothersome.'),
               (218, 0, 1, N'"If we can''t defeat them soon, it''ll be a"'),
               (218, 0, 2, N'horrible future for us. All my brothers'),
               (218, 0, 3, N'are fighting hard and I hope that you'),
               (218, 0, 4, N'will join them in this struggle!'),
               (218, 1, 0, N'"I really want to fight, but we need a"'),
               (218, 1, 1, N'Commander. I see no candidates here'),
               (218, 1, 2, N'"other than myself, but that''s because"'),
               (218, 1, 3, N'I''m afraid! Eh-hehe.'),
               (218, 2, 0, N'"Hahah! I''m not trying to escape, I will"'),
               (218, 2, 1, N'not leave you guys behind!'),
               (218, 3, 0, N'Always treat others with'),
               (218, 3, 1, N'the utmost respect. Maybe one day'),
               (218, 3, 2, N'your life will lie in their hands. Do they'),
               (218, 3, 3, N'dare save such a fool?'),
               (218, 3, 4, N'Be aware of this.'),
               (218, 4, 0, N'"Show me what you''re made of, Soldier!"'),
               (219, 0, 0, N'I heard that gate Master Tai is always talking'),
               (219, 0, 1, N'behind my back. Oh... that old coot!'),
               (219, 0, 2, N'I don''t remember offending him any.'),
               (219, 0, 3, N'Blast! He better not ruin my business.'),
               (219, 1, 0, N'People wish to know how my telekinesis works.'),
               (219, 1, 1, N'It simply is not something that can be taught.'),
               (219, 1, 2, N'"When you can bend the world with your mind,"'),
               (219, 1, 3, N'you may begin to understand.'),
               (219, 2, 0, N'My fee is based upon the distance traveled!'),
               (219, 2, 1, N'I have to charge you in order to make a'),
               (219, 2, 2, N'"living, I hope you can understand."'),
               (219, 3, 0, N'My! You are older than I thought!'),
               (219, 3, 1, N'"Oops, I''m so sorry, that was rude of me,"'),
               (219, 3, 2, N'please excuse me...'),
               (219, 4, 0, N'Don''t you know it''s not polite to ask a woman'),
               (219, 4, 1, N'her age? Don''t do it again!'),
               (220, 0, 0, N'Argh! How come I don¡¯t feel cold?'),
               (220, 0, 1, N'How can I call myself a Guard of Ling Chi'),
               (220, 0, 2, N'Fortress if I can¡¯t stand such cold weather?'),
               (220, 0, 3, N'Get out of my way. I''m on duty.'),
               (220, 1, 1, N'I¡¯m not sleeping!'),
               (220, 2, 0, N'Hello?'),
               (220, 3, 0, N'Guards are the symbol of bravery and courage.'),
               (220, 3, 1, N'"It would be wise to mind yourself, and"'),
               (220, 3, 2, N'not mess with us!'),
               (220, 4, 0, N'!!!!!'),
               (220, 4, 1, N'You scared me!'),
               (301, 0, 0, N'I have only one wish!!'),
               (301, 0, 1, N'To unify China!'),
               (301, 0, 2, N'Aha! God shouldn''t have abandoned us!'),
               (301, 0, 3, N'Let my soul burn in the flames of hell!!'),
               (301, 2, 0, N'Zhou Wuji was such a fool!'),
               (301, 2, 1, N'Life is the most precious thing!'),
               (301, 2, 2, N'"Oh, although we had some problems, I did not"'),
               (301, 2, 3, N'expect him to die so soon.'),
               (301, 2, 4, N'"Eh, another gate gone..."'),
               (301, 3, 0, N'"Shrin Kae is an outstanding talent,"'),
               (301, 3, 1, N'but he has a few weaknesses.'),
               (301, 3, 2, N'I think that as a ruler he'),
               (301, 3, 3, N'needs to be more ruthless.'),
               (301, 4, 0, N'"Ehlec Teroh,"'),
               (301, 4, 1, N'"so much is unknown about him,"'),
               (301, 4, 2, N'who would have thought he''d come back and'),
               (301, 4, 3, N'create his own Faction!!'),
               (301, 4, 4, N'China is simply so unpredictable...'),
               (302, 0, 0, N'"There are two others, just like me, that"'),
               (302, 0, 1, N'follow the Guardian. Overseeing the Guards is'),
               (302, 0, 2, N'"part of my duties, and I take care of"'),
               (302, 0, 3, N'any problems. You have any questions?'),
               (302, 1, 0, N'Only the people who survive the challenges of'),
               (302, 1, 1, N'the Nangin will reap the ultimate reward.'),
               (302, 1, 2, N'Our Faction is the best place to test your'),
               (302, 1, 3, N'courage. None of my disciples are cowardly.'),
               (302, 2, 0, N'I heard Fohchoy became'),
               (302, 2, 1, N'Guardian of the Royal Serpent.'),
               (302, 2, 2, N'This guy was always talented'),
               (302, 2, 3, N'"but I had no idea... I mean,"'),
               (302, 2, 4, N'I never expected that he was Darkbringer.'),
               (302, 3, 0, N'"It''s wonderful to pursue great power,"'),
               (302, 3, 1, N'but you have to work harder for it.'),
               (302, 3, 2, N'"If you are not confident, then you do not"'),
               (302, 3, 3, N'deserve to be a Grand Tiger'),
               (302, 3, 4, N'follower!'),
               (302, 4, 0, N'The Guardian puts his heart and soul into'),
               (302, 4, 1, N'unifying China.'),
               (302, 4, 2, N'How can you judge him when you'),
               (302, 4, 3, N'don''t know what''s going on!'),
               (302, 4, 4, N'Ridiculous?!'),
               (303, 0, 0, N'White Tiger Sabermen usually attack with'),
               (303, 0, 1, N'"slashes. In close range combat, saber is"'),
               (303, 0, 2, N'the most powerful weapon. I see your'),
               (303, 0, 3, N'physique is cut out to be a Saberman.'),
               (303, 0, 4, N'Do you want to learn Martial Arts?'),
               (303, 1, 0, N'"Long Spear is for attacking, Phurba is for far"'),
               (303, 1, 1, N'"range, but Thin Blade is good for defense."'),
               (303, 1, 2, N'Its quite safe for PK and hunting monsters.'),
               (303, 1, 3, N'"Of course it does has some weaknesses,"'),
               (303, 1, 4, N'but you can make it up by other means.'),
               (303, 2, 0, N'A lot of people are fighting in the Burning'),
               (303, 2, 1, N'"Woods. Thinking back, it''s just like the old"'),
               (303, 2, 2, N'times when I was a kid...'),
               (303, 2, 3, N'Daddy... Mommy...'),
               (303, 3, 0, N'Guardian Stah Reiki is my adopted father. He'),
               (303, 3, 1, N'"brought me up after my father was killed, and"'),
               (303, 3, 2, N'"promoted me to this position. I am grateful,"'),
               (303, 3, 3, N'and I will try my best to assist him. For'),
               (303, 3, 4, N'myself and for the future of our Faction!'),
               (303, 4, 0, N'Let''s go fight! Our disciples must always'),
               (303, 4, 1, N'"trust each other, and never kill each other!"'),
               (303, 4, 2, N'Offenders will be driven out!!'),
               (304, 0, 0, N'"There are all sorts of Long Spears, from"'),
               (304, 0, 1, N'"Demon ones, to things like Cyan Dragon Long"'),
               (304, 0, 2, N'Spear and the Demon Long Spear. They may have'),
               (304, 0, 3, N'"some disadvantages in close combat, but a real"'),
               (304, 0, 4, N'Long Spear Master can not be bound by distance'),
               (304, 1, 0, N'"Daoba Forest? I don''t know, I wasn''t there."'),
               (304, 1, 1, N'"I don''t know what happened, so just don''t"'),
               (304, 1, 2, N'ask me. Look for Quon if you really'),
               (304, 1, 3, N'want to know.'),
               (304, 2, 0, N'"Long Spear is an aggressive weapon, it''s"'),
               (304, 2, 1, N'quite unique compared to the other weapons.'),
               (304, 2, 2, N'"Pick up a Long Spear, if you''re looking for"'),
               (304, 2, 3, N'"excitement! Just remember, you must train"'),
               (304, 2, 4, N'real hard to bring it into play! Improving'),
               (304, 3, 0, N'"your abilities is crucial, but you also"'),
               (304, 3, 1, N'need to reinforce your weapons as well.'),
               (304, 3, 2, N'A lot of people have died for ignoring their'),
               (304, 3, 3, N'"weapon, you get it?"'),
               (304, 4, 0, N'"Compared to the older ones, the Long Spears"'),
               (304, 4, 1, N'"today looks heavier, but they have a much"'),
               (304, 4, 2, N'better performance record.'),
               (305, 0, 0, N'Dragon Tortoise Fighters understand the'),
               (305, 0, 1, N'importance of Curse. By concentrated'),
               (305, 0, 2, N'"training, they achieve an ideal combination"'),
               (305, 0, 3, N'between Curse and Magic. Once hit by a curse'),
               (305, 0, 4, N'the target will suffer illusions until death.'),
               (305, 1, 0, N'Phurba is used for long range attacks.'),
               (305, 1, 1, N'Even though the Long Spear and Thin Blade act'),
               (305, 1, 2, N'"as good close range attack, it''s an advantage"'),
               (305, 1, 3, N'to hit an enemy beyond his reach.'),
               (305, 2, 0, N'Sha-Tian often tells me to gather some'),
               (305, 2, 1, N'information. Our Dragon Tortoise Fighters'),
               (305, 2, 2, N'are really good at this.'),
               (305, 3, 0, N'Guardian Stah Reiki is truly a great leader.'),
               (305, 3, 1, N'He is far more brilliant than I had thought.'),
               (305, 3, 2, N'"I trust my judgment, and I¡¯m sure I made the"'),
               (305, 3, 3, N'right choice in following him.'),
               (305, 4, 0, N'I am quite suspicious about Ehlec Teroh''s'),
               (305, 4, 1, N'"intentions, challenging us with"'),
               (305, 4, 2, N'"these so called ""tests"". Haha!"'),
               (305, 4, 3, N'"He calls us unworthy, we will show"'),
               (305, 4, 4, N'him the might of the Grand Tiger.'),
               (306, 0, 0, N'I grow tired of dealing with my hammer'),
               (306, 0, 1, N'every single day! But if I put it down'),
               (306, 0, 2, N'"for a while, I just can¡¯t help having"'),
               (306, 0, 3, N'an itch. Well....maybe I have to'),
               (306, 0, 4, N'accept my gate....'),
               (306, 1, 0, N'My great great grandfather thought about'),
               (306, 1, 1, N'"forging an extremely powerful sword,"'),
               (306, 1, 2, N'but he never succeeded. Bah! Such a pity.'),
               (306, 1, 3, N'"It¡¯s my turn now, and I¡¯m trying to get some"'),
               (306, 1, 4, N'Materials. I wish I could fulfill his dreams..'),
               (306, 2, 0, N'Sometimes I produce equipment for the'),
               (306, 2, 1, N'other Factions. I will never refuse money and'),
               (306, 2, 2, N'"Materials. Hehe, and it would be boring if"'),
               (306, 2, 3, N'I only worked for people in my own Faction.'),
               (306, 3, 0, N'"It''s not about the money, but I can''t work"'),
               (306, 3, 1, N'without it. You can''t make weapons'),
               (306, 3, 2, N'without money! How would you get'),
               (306, 3, 3, N'Materials? Am I right? Especially in this'),
               (306, 3, 4, N'time of turmoil...'),
               (306, 4, 0, N'I heard the Guardian is upset about the Nangin'),
               (306, 4, 1, N'matter. That Ehlec Teroh is a fine young man!'),
               (306, 4, 2, N'I wish he would come to me and show'),
               (306, 4, 3, N'me his weapon. I would love for a chance to'),
               (306, 4, 4, N'duplicate such craftsmanship.'),
               (307, 0, 0, N'Sometimes it''s boring doing business here.'),
               (307, 0, 1, N'I don''t even have sunshine...'),
               (307, 0, 2, N'"Good grief, isn''t this bad for my skin?"'),
               (307, 0, 3, N'I hope this doesn''t affect business...'),
               (307, 1, 0, N'"Did you know? When running this business,"'),
               (307, 1, 1, N'"the less you dress, the more you get. I don¡¯t"'),
               (307, 1, 2, N'mind exposing more if I can get more money'),
               (307, 1, 3, N'"for it, but being naked is not so appropriate"'),
               (307, 1, 4, N'"right? Hehe! Boy, where are you looking?"'),
               (307, 2, 0, N'Although I have reinforced your weapon in'),
               (307, 2, 1, N'"the past, I can''t do it very often."'),
               (307, 2, 2, N'It can actually be quite painful for me.'),
               (307, 3, 0, N'"My skin is getting rough lately, so I can''t"'),
               (307, 3, 1, N'expose as much as I could before... Oh'),
               (307, 3, 2, N'"well, forget it, nothing wrong with wearing a"'),
               (307, 3, 3, N'"dress, at least I won¡¯t feel so cold, haha!"'),
               (307, 4, 0, N'"Sometimes you wish to wear other clothes,"'),
               (307, 4, 1, N'"huh? Well, how about some light clothes?"'),
               (307, 4, 2, N'It feels good to try on some other clothes'),
               (307, 4, 3, N'occasionally.'),
               (308, 0, 0, N'Have you ever seen a man''s internal organs?'),
               (308, 0, 1, N'I¡¯m very experienced when it comes to surgery.'),
               (308, 0, 2, N'"Aha, but surgery costs money. Do you have any"'),
               (308, 0, 3, N'money? Haha. Would you believe I¡¯ve been called'),
               (308, 0, 4, N'a manic for curing people by surgery?'),
               (308, 1, 0, N'Some things can¡¯t be explained by science.'),
               (308, 1, 1, N'"People say I¡¯m cold-blooded, but how is that"'),
               (308, 1, 2, N'even possible? What am I suppose to do?'),
               (308, 2, 0, N'"Weird, I have always wanted to know how this"'),
               (308, 2, 1, N'poison was made. There should be an antidote!!'),
               (308, 2, 2, N'"I''m sorry but I can''t make one, it maybe"'),
               (308, 2, 3, N'because I''m not good enough.'),
               (308, 2, 4, N'Dang! Looks like I have to find someone else.'),
               (308, 3, 0, N'Is the Guardian in good health now?'),
               (308, 3, 1, N'His health will decline if he works too hard.'),
               (308, 3, 2, N'"I hope he can take care of himself,"'),
               (308, 3, 3, N'he is the backbone of our Faction!'),
               (309, 0, 0, N'Why are you comparing me with other people?'),
               (309, 0, 1, N'Their moves are way too far behind to be'),
               (309, 0, 2, N'able to catch up with mine!!'),
               (309, 1, 0, N'I¡¯m the first one to find this Mystical Site'),
               (309, 1, 1, N'"I told everyone about it, one after another."'),
               (309, 1, 2, N'"Good grief! Luckily the place is enormous, or"'),
               (309, 1, 3, N'how else could we contain the horde'),
               (309, 1, 4, N'of people that come to see it.'),
               (309, 2, 0, N'But their abilities are simply no match for'),
               (309, 2, 1, N'mine. Neither teleportation nor telekinesis'),
               (309, 2, 2, N'can beat my travel charms! They''re instant!'),
               (309, 3, 0, N'I always tell friends who go into'),
               (309, 3, 1, N'the war to stay alive and fight hard.'),
               (309, 3, 2, N'"While there is life, there is hope."'),
               (310, 0, 0, N'They said that the 12 legions were destroyed'),
               (310, 0, 1, N'"many years ago, by the Legacy Warrior, but"'),
               (310, 0, 2, N'somehow they survived.'),
               (310, 0, 3, N'Although all Factions seem to want to forget...'),
               (310, 0, 4, N'but...'),
               (310, 1, 0, N'Why don''t you speak to me about the Faction'),
               (310, 1, 1, N'"matters? In the past, there weren''t"'),
               (310, 1, 2, N'"the Factions you see now. Back then, the"'),
               (310, 1, 3, N'"12 legions tried again to dominate the lands,"'),
               (310, 1, 4, N'but they had no control. Always stuck in war.'),
               (310, 2, 0, N'"You ought to know by looking at my left leg,"'),
               (310, 2, 1, N'"and the scars on my forehead. Aha, that¡¯s the"'),
               (310, 2, 2, N'result of the fighting. I was always trying to'),
               (310, 2, 3, N'prevail over others when I was young.'),
               (310, 2, 4, N'"I will not regret, we were all young once."'),
               (310, 3, 0, N'"Some stories I can¡¯t remember, because"'),
               (310, 3, 1, N'my memory is getting worse as I grow older...'),
               (310, 3, 2, N'"Well, I still remember what I need,"'),
               (310, 3, 3, N'otherwise I wouldn''t be here.'),
               (310, 4, 0, N'I¡¯m not certain whether it''s good or bad to'),
               (310, 4, 1, N'"be an old man, but now, I appreciate this"'),
               (310, 4, 2, N'peaceful life. Maybe it''s because I¡¯m tired'),
               (310, 4, 3, N'"after all these years, that I have no more"'),
               (310, 4, 4, N'desires.'),
               (311, 0, 0, N'"Aha, you know why everyone says that I¡¯m"'),
               (311, 0, 1, N'smart? It''s because I know what you want'),
               (311, 0, 2, N'to sell! That¡¯s why! Want to try?'),
               (311, 0, 3, N'Let me guess what you want to sell.'),
               (311, 1, 0, N'"I have always been a rich man,"'),
               (311, 1, 1, N'"well, it''s because I made a fortune in this"'),
               (311, 1, 2, N'business. The more money you'),
               (311, 1, 3, N'"have, the higher chance of accomplishing"'),
               (311, 1, 4, N'something significant.'),
               (311, 2, 0, N'"Sometimes when the people are changed,"'),
               (311, 2, 1, N'they will come to me and cry.'),
               (311, 2, 2, N'"Anyway, only fools get changed..."'),
               (311, 2, 3, N'Just remember to always keep yourself alert.'),
               (311, 3, 0, N'This abacus was handed down to me from my'),
               (311, 3, 1, N'"grandpa. I suppose it''s an antique,"'),
               (311, 3, 2, N'haha. I bet it will get a good price!'),
               (311, 4, 0, N'Recently my hair loss is getting worse.'),
               (311, 4, 1, N'"Huh, maybe I have too much inner heat."'),
               (311, 4, 2, N'"Well, I was told its good to be vigorous,"'),
               (311, 4, 3, N'but maybe not in such extreme amounts.'),
               (312, 0, 0, N'"I want to travel, but I don¡¯t have"'),
               (312, 0, 1, N'"any money. Well, even if I did have"'),
               (312, 0, 2, N'"money, the world is just too"'),
               (312, 0, 3, N'"dangerous. Uhg, forget it, I had better"'),
               (312, 0, 4, N'keep doing my business here.'),
               (312, 1, 0, N'......'),
               (312, 1, 1, N'Why are you staring at me like that?'),
               (312, 1, 3, N'Tell me if you need anything.'),
               (312, 2, 0, N'How about this bundle on my back? Does it'),
               (312, 2, 1, N'"look heavy? Well, that''s because it contains"'),
               (312, 2, 2, N'all my most valuable items. I usually never'),
               (312, 2, 3, N'"put it down. Well, don¡¯t worry, I¡¯m stronger"'),
               (312, 2, 4, N'than you think.'),
               (312, 3, 0, N'Some people say I¡¯m stingy!'),
               (312, 3, 1, N'"I hear that quite often, but I still"'),
               (312, 3, 2, N'have plenty of business. Do you'),
               (312, 3, 3, N'think that stinginess is some sort of'),
               (312, 3, 4, N'beauty? Hahahaha.'),
               (312, 4, 0, N'"To survive Demong the Grand Tiger, you need to"'),
               (312, 4, 1, N'"have the real stuff, or you will be tortured"'),
               (312, 4, 2, N'by those creatures until they get satisfied.'),
               (312, 4, 3, N'That¡¯s why I have been working so hard.'),
               (313, 0, 0, N'"I''m not expecting anything from anyone here,"'),
               (313, 0, 1, N'"no one can beat me, boring amateurs!"'),
               (313, 0, 2, N'"Uh? Are you interested? Well, you better go!"'),
               (313, 0, 3, N'I better not see you cry if you lose'),
               (313, 0, 4, N'all your stakes!');

        INSERT INTO world.NpcSpeeches (NpcId, SpeechGroup, SpeechIndex, Text)
        VALUES (313, 1, 0, N'"Vital Gambling, is a game of China."'),
               (313, 1, 1, N'"Winning or losing is decided in one round,"'),
               (313, 1, 2, N'its really fun. You may end up with'),
               (313, 1, 3, N'"everything, or with nothing at all."'),
               (313, 2, 0, N'"What he did to my eyes was due to gambling,"'),
               (313, 2, 1, N'"but after that accident, I developed a more"'),
               (313, 2, 2, N'"interesting way of gambling, aha!"'),
               (313, 2, 3, N'Maybe I was born for gambling.'),
               (313, 3, 0, N'What am I going to do with all this money?'),
               (313, 3, 1, N'"Do I have to tell you? Of course, bet more!"'),
               (313, 3, 2, N'Winning and losing is the best in gambling!'),
               (314, 0, 0, N'Key.... are you staring at my ugly face?'),
               (314, 0, 1, N'"Although I look ugly now, I used to be a good"'),
               (314, 0, 2, N'looking man when a was younger. Handsome'),
               (314, 0, 3, N'"Domgi, and loved by millions of people!"'),
               (314, 0, 4, N'Hahaha!'),
               (314, 1, 0, N'Sometimes I would like to experience the'),
               (314, 1, 1, N'"peaceful life. After all, Martial Arts World"'),
               (314, 1, 2, N'is in a turbulent situation. Peace.. It''s'),
               (314, 1, 3, N'only a dream.'),
               (315, 0, 0, N'"Our city has a solid wall, it keeps monsters"'),
               (315, 0, 1, N'"away, let anyone who has the guts to try and"'),
               (315, 0, 2, N'pass!! I will teach him a lesson.'),
               (315, 0, 3, N'Hahahahah....'),
               (315, 1, 0, N'....'),
               (315, 1, 1, N'I feel sleepy... Leave me alone...'),
               (315, 2, 0, N'"I have a streak line on my eyes, hehe."'),
               (315, 2, 1, N'People will not notice when I fall a sleep.'),
               (315, 3, 0, N'Hi!'),
               (315, 3, 1, N'Don''t put my leg!'),
               (315, 4, 0, N'"The Guards who are holding the banners, are"'),
               (315, 4, 1, N'tired? Of course they are! But if you don¡¯t'),
               (315, 4, 2, N'"hold it, you can only guess what would happen"'),
               (315, 4, 3, N'if Sha-Tian or the Guardian were to find out?'),
               (315, 4, 4, N'So just keep your mouth shut.'),
               (316, 0, 0, N'Sha-Tian¡¯s Martial Arts has become'),
               (316, 0, 1, N'even more powerful over the past few years.'),
               (316, 0, 2, N'it has killed countless Martial Masters.'),
               (316, 1, 0, N'"Take a good look, and then look again,"'),
               (316, 1, 1, N'can you tell the difference between me and'),
               (316, 1, 2, N'other Guards? A lot of people can¡¯t tell.'),
               (316, 1, 3, N'This is exactly what I want!'),
               (316, 1, 4, N'I like keeping a low profile!'),
               (316, 2, 0, N'Ikusa Mountain is a well known place'),
               (316, 2, 1, N'"now days, but in the old days"'),
               (316, 2, 2, N'only people above Master Level could'),
               (316, 2, 3, N'"enter that place,"'),
               (316, 3, 0, N'"Oh, I feel sleepy."'),
               (316, 4, 0, N'"Tell me if you want to go to the battle,"'),
               (316, 4, 1, N'because I have to record your name.'),
               (316, 4, 2, N'"If you don''t, no one will take care of you"'),
               (316, 4, 3, N'if you are killed'),
               (317, 0, 0, N'"Young people are so combative, its not"'),
               (317, 0, 1, N'"really bad, but you need an appropriate"'),
               (317, 0, 2, N'"occasion. If you fight blindly, it may"'),
               (317, 0, 3, N'undermine your inner balance.'),
               (317, 0, 4, N'That would be something terrible.'),
               (317, 1, 0, N'"You are really good in Martial Arts,"'),
               (317, 1, 1, N'I would like to learn from you if I had the'),
               (317, 1, 2, N'chance.'),
               (317, 2, 0, N'Can you stop saying I look just like the'),
               (317, 2, 1, N'others?'),
               (317, 2, 2, N'"It''s just too much, I¡¯m getting sick!"'),
               (317, 3, 0, N'"Joking is alright,"'),
               (317, 3, 1, N'but don''t go too far!'),
               (317, 4, 0, N'Come to me anytime if you need anything.'),
               (318, 0, 0, N'The other Factions are really bothersome.'),
               (318, 0, 1, N'"If we can''t defeat them soon, it''ll be a"'),
               (318, 0, 2, N'horrible future for us. All my brothers'),
               (318, 0, 3, N'are fighting hard and I hope that you'),
               (318, 0, 4, N'will join them in this struggle!'),
               (318, 1, 0, N'"I really want to fight, but we need a"'),
               (318, 1, 1, N'Commander. I see no candidates here'),
               (318, 1, 2, N'"other than myself, but that''s because"'),
               (318, 1, 3, N'I''m afraid! Eh-hehe.'),
               (318, 2, 0, N'"Hahah! I''m not trying to escape, I will"'),
               (318, 2, 1, N'not leave you guys behind!'),
               (318, 3, 0, N'Always treat others with'),
               (318, 3, 1, N'the utmost respect. Maybe one day'),
               (318, 3, 2, N'your life will lie in their hands. Do they'),
               (318, 3, 3, N'dare save such a fool?'),
               (318, 3, 4, N'Be aware of this.'),
               (318, 4, 0, N'"Show me what you''re made of, Soldier!"'),
               (319, 0, 0, N'Why are you comparing me with other people?'),
               (319, 0, 1, N'Do you think my moves are way too far behind'),
               (319, 0, 2, N'to be able to catch up with the others?'),
               (319, 1, 0, N'Their so-called arts are no match for mine.'),
               (319, 1, 1, N'Neither teleportation nor telekinesis can'),
               (319, 1, 2, N'can beat my travel charms.'),
               (319, 1, 3, N'That¡¯s why I am the best!'),
               (319, 2, 0, N'"You have to stay alive, even the"'),
               (319, 2, 1, N'death of one or two will be a big loss'),
               (319, 2, 2, N'for me!'),
               (319, 3, 0, N'What am I suppose to eat to lose weight...'),
               (319, 3, 1, N'"Oh, walking is getting difficult for me."'),
               (319, 4, 0, N'That old Herbalist is developing a new'),
               (319, 4, 1, N'"diet pill, but I don''t trust him..."'),
               (319, 4, 2, N'That old fellow... I wonder if he will try to'),
               (319, 4, 3, N'poison me.'),
               (320, 0, 0, N'"Our city has a solid Wall, it will "'),
               (320, 0, 1, N'"away, let anyone who has the guts to try and"'),
               (320, 0, 2, N'pass!! I will teach him a lesson.'),
               (320, 0, 3, N'Hahahahah....'),
               (320, 1, 0, N'....'),
               (320, 1, 1, N'I feel sleepy... Leave me alone...'),
               (320, 2, 0, N'"I have a streak line on my eyes, hehe."'),
               (320, 2, 1, N'People will not notice when I fall a sleep.'),
               (320, 3, 0, N'Hi!'),
               (320, 3, 1, N'Don''t put my leg!'),
               (320, 4, 0, N'"The Guards who are holding the banners, are"'),
               (320, 4, 1, N'tired? Of course they are! But if you don¡¯t'),
               (320, 4, 2, N'"hold it, you can only guess what would happen"'),
               (320, 4, 3, N'if Sha-Tian or the Guardian were to find out?'),
               (320, 4, 4, N'So just keep your mouth shut.'),
               (401, 0, 0, N'We Messengers are sent to other regions and'),
               (401, 0, 1, N'risk our lives in order to execute dangerous'),
               (401, 0, 2, N'"missions. Messengers are always changing,"'),
               (401, 0, 3, N'I¡¯m the one that¡¯s lasted the longest. Hahah!'),
               (401, 1, 0, N'"Wow, that''s quite scary!!"'),
               (401, 1, 1, N'I just don''t feel safe here!'),
               (401, 2, 0, N'Noble Dragon are a well balanced Faction. They'),
               (401, 2, 1, N'don''t favor weapon nor physique but if'),
               (401, 2, 2, N'"they get some support from a party, they can"'),
               (401, 2, 3, N'turn into a force to be reckoned with.'),
               (401, 2, 4, N'This is the same for the other two Factions.'),
               (401, 3, 0, N'"The Nangin are also very powerful,"'),
               (401, 3, 1, N'I can''t imagine how they can be so strong.'),
               (402, 0, 0, N'I left Ling Chi Fortress at the same time my'),
               (402, 0, 1, N'blood sister opened up a tailor shop'),
               (402, 0, 2, N'in the town.'),
               (402, 0, 3, N'"Her name is Terai, I wonder how she is doing."'),
               (403, 0, 0, N'This is where ancient Martial Masters'),
               (403, 0, 1, N'would seal themselves with the Evil Sword'),
               (403, 0, 2, N'for washing their sins away.'),
               (403, 0, 3, N'I¡¯m suppose to find the Evil Sword.'),
               (404, 0, 0, N'You know what a Martial Adept is?'),
               (404, 0, 1, N'Martial Adepts are good at Martial Art'),
               (404, 0, 2, N'and they also know how to conduct themselves'),
               (404, 0, 3, N'in a dignified and gracious manner.'),
               (404, 0, 4, N'You? Not even close!'),
               (405, 0, 0, N'Ooh? Are you trying to say I have a big head?'),
               (405, 0, 1, N'"Uh, never mind, I was born like this."'),
               (405, 0, 2, N'Say whatever you want to say.'),
               (405, 0, 3, N'"Haha, big heads have big brains."'),
               (406, 0, 0, N'Ugh! I''m writing my report again.....'),
               (406, 0, 1, N'Every day....'),
               (406, 0, 2, N'Day after day....'),
               (406, 0, 3, N'The day after tomorrow....'),
               (406, 0, 4, N'Next month....'),
               (407, 0, 0, N'You know? Someone in town is really good'),
               (407, 0, 1, N'at painting.'),
               (407, 0, 2, N'"You know who he is? Hehe, that''s me!"'),
               (407, 0, 3, N'I would paint one for you if I had the time.'),
               (407, 0, 4, N'"Aha, its ok, no charge!"'),
               (408, 0, 0, N'I¡¯m afraid to die. But I have to hang on'),
               (408, 0, 1, N'for the family.'),
               (408, 0, 2, N'"Huh, anyway, they pay me well,"'),
               (408, 0, 3, N'and I can feed my family!'),
               (409, 0, 0, N'"Key, when are you going to give me the answer?"'),
               (409, 0, 1, N'Its been so long.'),
               (409, 0, 2, N'When are you going to tell me?'),
               (409, 0, 3, N'I can¡¯t wait.'),
               (410, 0, 0, N'Painting? You made the right choice.'),
               (410, 0, 1, N'"I can say, my painting skills are perfect!"'),
               (410, 0, 2, N'Aha!'),
               (410, 0, 3, N'Want me to paint for you? Just ask me.'),
               (410, 1, 0, N'"I really miss my children, they are twins.."'),
               (410, 1, 1, N'"My boy looks just like me, and my girl looks"'),
               (410, 1, 2, N'just like her mother. I really miss them¡¦'),
               (411, 0, 0, N'"If we only use Martial Arts,"'),
               (411, 0, 1, N'it would be quite tough to beat me.'),
               (411, 0, 2, N'To survive in this world is not just about'),
               (411, 0, 3, N'Martial Arts though. I can survive...'),
               (411, 0, 4, N'but can you? Hahaha!'),
               (411, 1, 0, N'You know the Lord of China?'),
               (411, 1, 1, N'Only the man with the best Martial Arts can be'),
               (411, 1, 2, N'elected as the Lord of China.'),
               (411, 1, 3, N'"Let me think about it,"'),
               (411, 1, 4, N'who will be the next Lord of China?'),
               (412, 0, 0, N'......'),
               (412, 0, 1, N'What a boring day...'),
               (412, 0, 2, N'I can''t take this anymore...'),
               (413, 0, 0, N'"Look at this building, it''s a mess!"'),
               (413, 0, 1, N'How can our building be built in such way!'),
               (413, 0, 2, N'That''s unacceptable! Simply unacceptable!!'),
               (414, 0, 0, N'I want to put on some weight......'),
               (414, 0, 1, N'so that I won''t look like the wind may'),
               (414, 0, 2, N'blow me away at any moment.'),
               (415, 0, 0, N'"Sometimes I enjoy looking up at the sky,"'),
               (415, 0, 1, N'It is just so peaceful...'),
               (415, 0, 2, N'hmm...'),
               (415, 0, 3, N'Why can''t be that way on earth?'),
               (416, 0, 0, N'Huh......'),
               (416, 0, 1, N'I want to sleep......'),
               (416, 0, 2, N'Leave me alone......'),
               (416, 0, 3, N'ZzZzZzZz......'),
               (417, 0, 0, N'Everything is under control!'),
               (417, 0, 1, N'Hahaha!'),
               (417, 0, 2, N'"Oh, you heard that?"'),
               (417, 0, 3, N'"Actually, you heard and saw nothing,"'),
               (417, 0, 4, N'got it?'),
               (418, 0, 0, N'What people think is so unpredictable...'),
               (418, 0, 1, N'Why do you have to be so hard on yourself?'),
               (419, 0, 0, N'......'),
               (419, 0, 1, N'"Do not disturb me, I am on duty and have no"'),
               (419, 0, 2, N'business with you.'),
               (419, 1, 0, N'Bah! Recently there have been a lot of'),
               (419, 1, 1, N'new recruits coming in.'),
               (419, 1, 2, N'When I look at them it reminds me of'),
               (419, 1, 3, N'the old days.'),
               (419, 1, 4, N'Such cherished old days...'),
               (420, 0, 0, N'......'),
               (420, 0, 1, N'"Do not disturb me, I am on duty and have no"'),
               (420, 0, 2, N'business with you.'),
               (421, 0, 0, N'......'),
               (421, 0, 1, N'"Do not disturb me, I am on duty and have no"'),
               (421, 0, 2, N'business with you.'),
               (422, 0, 0, N'......'),
               (423, 0, 0, N'......'),
               (424, 0, 0, N'......');

